    /// Exercises FFmpeg's actual `-n` behavior against the production argument
    /// builder. Ignored in default CI because the Rust test job deliberately
    /// has no FFmpeg dependency; run explicitly on recording-studio hosts.
    #[tokio::test]
    #[ignore = "spawns ffmpeg and writes media; run with --ignored"]
    async fn real_ffmpeg_export_creates_absent_child_and_rejects_preexisting_output() {
        let directory =
            std::env::temp_dir().join(format!("videorc-real-mp4-export-test-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&directory).unwrap();
        let input = directory.join("recording.mkv");
        let fixture = std::process::Command::new("ffmpeg")
            .args([
                "-y",
                "-hide_banner",
                "-loglevel",
                "error",
                "-f",
                "lavfi",
                "-i",
                "color=size=64x64:rate=10:color=black",
                "-f",
                "lavfi",
                "-i",
                "anullsrc=channel_layout=stereo:sample_rate=48000",
                "-t",
                "0.2",
                "-c:v",
                "mpeg4",
                "-c:a",
                "pcm_s16le",
            ])
            .arg(&input)
            .status()
            .expect("ffmpeg should be on PATH for this ignored test");
        assert!(fixture.success(), "fixture FFmpeg failed");

        let staging = prepare_mp4_export_staging(&directory.join("recording.mp4")).unwrap();
        assert!(!staging.output_path.exists());
        export_mp4_from_mkv("ffmpeg", &input, &staging.output_path)
            .await
            .unwrap();
        assert!(std::fs::metadata(&staging.output_path).unwrap().len() > 0);

        let preexisting = directory.join("preexisting.mp4");
        std::fs::write(&preexisting, b"must survive").unwrap();
        assert!(
            export_mp4_from_mkv("ffmpeg", &input, &preexisting)
                .await
                .is_err()
        );
        assert_eq!(std::fs::read(&preexisting).unwrap(), b"must survive");

        cleanup_prepared_mp4_export_staging(&staging).unwrap();
        std::fs::remove_dir_all(directory).unwrap();
    }

    /// Runs the production microphone filter/duration policy through real
    /// FFmpeg: a one-second mic EOF must become silence until the three-second
    /// video EOF, then `-shortest` must terminate the padded output.
    #[test]
    #[ignore = "spawns ffmpeg and ffprobe; run on recording-studio hosts"]
    fn real_ffmpeg_microphone_eof_keeps_video_as_the_output_clock() {
        let directory = std::env::temp_dir().join(format!(
            "videorc-real-microphone-continuity-test-{}",
            Uuid::new_v4()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let output = directory.join("microphone-continuity.mkv");
        let input_layout = microphone_input_layout(false);
        let audio = AudioSettings::default();
        let mut args = vec![
            "-y".to_string(),
            "-hide_banner".to_string(),
            "-loglevel".to_string(),
            "error".to_string(),
            "-f".to_string(),
            "lavfi".to_string(),
            "-i".to_string(),
            "color=size=64x64:rate=10:duration=3".to_string(),
            "-f".to_string(),
            "lavfi".to_string(),
            "-i".to_string(),
            "sine=frequency=440:sample_rate=48000:duration=1".to_string(),
            "-map".to_string(),
            "0:v".to_string(),
        ];
        append_audio_output_args(&mut args, &input_layout);
        args.extend(["-c:v".to_string(), "mpeg4".to_string()]);
        append_audio_encoding_with_video_clock(&mut args, &input_layout, &audio, true, false);
        args.push(output.display().to_string());

        let status = std::process::Command::new("ffmpeg")
            .args(&args)
            .status()
            .expect("ffmpeg should be on PATH for this ignored test");
        assert!(status.success(), "microphone continuity FFmpeg failed");

        let probe = std::process::Command::new("ffprobe")
            .args([
                "-v",
                "error",
                "-show_entries",
                "format=duration",
                "-of",
                "default=noprint_wrappers=1:nokey=1",
            ])
            .arg(&output)
            .output()
            .expect("ffprobe should be on PATH for this ignored test");
        assert!(probe.status.success(), "microphone continuity probe failed");
        let duration = String::from_utf8(probe.stdout)
            .unwrap()
            .trim()
            .parse::<f64>()
            .unwrap();
        assert!(
            (2.9..=3.1).contains(&duration),
            "audio EOF shortened the {duration:.3}s output instead of padding to video EOF"
        );

        std::fs::remove_dir_all(directory).unwrap();
    }

